const CalendarGrid: React.FC<{
  lineColor: string;
  highlightColor: string;
  frame: number;
  fps: number;
}> = ({ lineColor, highlightColor, frame, fps }) => {
  const rows = 5;
  const cols = 7;
  const targetIndex = 17; // A day somewhere in the middle (e.g., 3rd row)

  // Calendar entrance
  const scale = spring({
    frame,
    fps,
    config: { damping: 15 },
    durationInFrames: 30,
  });

  // Highlight entrance (delayed)
  const highlightProgress = spring({
    frame: frame - 25,
    fps,
    config: { stiffness: 200, damping: 20 },
  });

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: `repeat(${cols}, 1fr)`,
        gap: 8,
        padding: 20,
        border: `4px solid ${lineColor}`,
        borderRadius: 20,
        width: 400,
        height: 320,
        transform: `scale(${scale})`,
        backgroundColor: "rgba(255,255,255,0.8)",
      }}
    >
      {Array.from({ length: rows * cols }).map((_, i) => {
        const isTarget = i === targetIndex;
        return (
          <div
            key={i}
            style={{
              border: `2px solid ${lineColor}`,
              borderRadius: 4,
              position: "relative",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {isTarget && (
              <div
                style={{
                  width: "70%",
                  height: "70%",
                  backgroundColor: highlightColor,
                  borderRadius: "50%",
                  transform: `scale(${highlightProgress})`,
                  opacity: highlightProgress,
                }}
              />
            )}
          </div>
        );
      })}
    </div>
  );
};

// --- Main Component ---

const CalendarPayday: React.FC<CalendarPaydayProps> = ({
  backgroundColor = "#f3f4f6",
  transparentBackground = false,
  durationInSeconds = 5,
  calendarLineColor = "#374151",
  highlightColor = "#22c55e",
  dollarColor = "#15803d",
  calendarScale = 1,
  dollarCount = 20,
}) => {
  useFontLoader(["Inter"]); // Not using font text, but good practice if extending
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Generate deterministic dollar drops
  const drops = useMemo(() => {
    return Array.from({ length: dollarCount }).map((_, i) => {
      const seed = `dollar-${i}`;
      const xPercent = random(seed) * 100; // 0-100% width
      const delay = 35 + random(seed + "delay") * 40; // Start falling after frame 35
      const speed = 0.5 + random(seed + "speed") * 1.0; // Random speed factor
      const size = 40 + random(seed + "size") * 40; // Random size 40-80px
      const rotation = random(seed + "rot") * 360; // Initial rotation
      return { xPercent, delay, speed, size, rotation };
    });
  }, [dollarCount]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Centered Calendar */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
        }}
      >
        <div style={{ transform: `scale(${calendarScale})` }}>
          <CalendarGrid
            lineColor={calendarLineColor}
            highlightColor={highlightColor}
            frame={frame}
            fps={fps}
          />
        </div>
      </AbsoluteFill>

      {/* Falling Dollars Layer */}
      <AbsoluteFill style={{ zIndex: 20, pointerEvents: "none" }}>
        {drops.map((drop, i) => {
          // Falling logic
          const fallProgress = interpolate(
            frame - drop.delay,
            [0, 100 / drop.speed], // Duration depends on speed
            [-100, height + 100], // From above screen to below
            { extrapolateRight: "extend", extrapolateLeft: "clamp" }
          );

          // Don't render if it hasn't started falling
          if (frame < drop.delay) return null;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: `${drop.xPercent}%`,
                top: 0,
                transform: `translateY(${fallProgress}px) rotate(${drop.rotation}deg)`,
              }}
            >
              <DollarIcon color={dollarColor} size={drop.size} />
            </div>
          );
        })}
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default CalendarPayday;